Boolean dei_sc_icon_runtime_reset(  Notify_Pld_Runtime runtime )
{    
    dei_sc_info_set( DEI_SC_INFO_RUNTIME_NOTIFYAINING  , runtime ) ;        
    dei_sc_info_set( DEI_SC_INFO_RUNTIME_PROGRAMMED    , runtime ) ;        

	dei_sc_automatic_page_update();
    
    return dei_sc_tx( DEI_SC_ACK_RUNTIME_CONFIRM ,DEI_SC_NORMAL_TX , 100 ) ;     
}

